import {buildTeachingStats} from './teaching-stats.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=value=>value===null?'—':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(value);
const average=value=>value===null?'—':value.toFixed(2);
const equal=(a,b)=>a===b||a!==null&&b!==null&&Math.abs(a-b)<1e-9;
function value(before,current,{unit='',decimal=false,dirty=false}={}){const fmt=decimal?average:n;return `${dirty&&!equal(before,current)?`<span class="stats-before">${fmt(before)} → </span>`:''}${fmt(current)}${current===null?'':`<small>${unit}</small>`}`;}
export function teachingOverview(ctx,view,{dirty=false,expanded=false}={}){
  const current=buildTeachingStats(ctx,view),before=buildTeachingStats(ctx,ctx.sourceView),a=before.overall,b=current.overall;
  const metrics=[['averageClassLoad','人均带班量','班/师',true,'班级总数÷本学期教师人数'],['averagePrepHeads','人均课头','个/师',true,'各老师按年级×归并科目×难度层级去重后，合计课头÷教师人数'],['averageClassSize','班均人数','人/班',true,'各班有效报名人次之和÷班级总数'],['classCount','班级总数','个',false,'系列授课班计数；单次调课和合并源引用不额外计班'],['teacherCount','教师人数','人',false,'本学期校区名册，包含方案调整后本范围暂无班级的老师；总计按教师去重'],['lessonCount','课次','次',false,'当前方案全期实际课次数'],['teachingHours','授课时长','小时',false,'当前校区全期实际授课时长，不含缺少完整课程资料的外部课']];
  return `<section class="teaching-overview" aria-label="校区教学统计" data-testid="teaching-overview"><div class="stats-heading"><div><h2>教学概览</h2><span>当前课程周期 · 全部授课日 · ${dirty?'当前方案（未执行）':'起始安排'}</span></div><div class="stats-heading-actions"><details class="stats-definitions"><summary>统计口径</summary><div><p>人均带班量＝班级总数÷老师总数。</p><p>个人课头按年级×科目×ABC层级去重；人均课头＝各老师个人课头合计÷老师数，平行班不重复增加。</p><p>班均＝有效报名人次÷班数；口语并入英语、阅读并入语文。同科进度不同不额外拆课头。</p><p>教师基数沿本学期名册，合班后无班老师仍计入。兼科在各科分别计数，总计教师去重。</p><p>含置灰班级，授课日/高亮筛选不缩小当前课程周期统计；已知外部课时仍在原教师课量明细另计。</p></div></details><button type="button" data-action="teacher-stats" data-id="ALL">教师明细</button></div></div><div class="summary-bar" aria-label="课量汇总">${metrics.map(([key,label,unit,decimal,title])=>`<div class="summary-item" data-stat-key="${key}" title="${esc(title)}"><span>${label}</span><strong>${value(a[key],b[key],{unit,decimal,dirty})}</strong>${key==='averageClassLoad'?`<span class="stats-fraction">${b.classCount}班 / ${b.teacherCount}位教师</span>`:key==='averagePrepHeads'?`<span class="stats-fraction">${b.prepCount}个课头 / ${b.teacherCount}位教师</span>`:key==='averageClassSize'?`<span class="stats-fraction">${b.enrollmentCount}报名人次 / ${b.classCount}班</span>`:''}</div>`).join('')}</div><button type="button" class="subject-stats-toggle" data-action="toggle-subject-stats" aria-expanded="${expanded}" aria-controls="subject-stats-detail" aria-label="${expanded?'收起':'展开'}分科详情"><span>分科统计</span><span class="subject-stats-toggle-action">${expanded?'收起':'展开'}详情 <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span></button><div id="subject-stats-detail" class="subject-stats-scroll" ${expanded?'':'hidden'}><table class="subject-stats-table" aria-label="分科教学统计"><thead><tr><th>科目</th><th>班级数</th><th>教师数</th><th>人均带班量</th><th>课头总数</th><th>人均课头</th><th>班均人数</th></tr></thead><tbody>${current.subjects.map(row=>{const old=before.subjects.find(x=>x.subject===row.subject)??row;return `<tr data-stat-subject="${esc(row.subject)}"><th scope="row"><button type="button" data-action="teacher-stats" data-id="${esc(row.subject)}">${esc(row.subject)}</button></th>${[['classCount',false],['teacherCount',false],['averageClassLoad',true],['prepCount',false],['averagePrepHeads',true],['averageClassSize',true]].map(([key,decimal])=>`<td data-stat-key="${key}">${value(old[key],row[key],{decimal,dirty})}</td>`).join('')}</tr>`;}).join('')||'<tr><td colspan="7">本范围暂无学科班级</td></tr>'}</tbody></table></div></section>`;
}
export function teacherStatsDetail(ctx,view,subject='ALL'){
  const stats=buildTeachingStats(ctx,view),group=stats.subjects.find(s=>s.subject===subject),rows=group?group.teachers:stats.teachers;
  return `<div class="teacher-stats-filter"><label for="stats-subject">科目</label><select id="stats-subject"><option value="ALL" ${subject==='ALL'?'selected':''}>全部科目</option>${stats.subjects.map(s=>`<option value="${esc(s.subject)}" ${subject===s.subject?'selected':''}>${esc(s.subject)}</option>`).join('')}</select><span>${rows.length}位教师 · 当前方案</span></div><div class="teacher-stats-scroll"><table class="review-table teacher-stats-table" aria-label="教师个人带班与课头"><thead><tr><th>教师</th><th>科目</th><th>带班量</th><th>课头数</th><th>课头明细（年级·科目·层级）</th><th>班均人数</th></tr></thead><tbody>${rows.map(t=>`<tr data-stat-teacher="${esc(t.id)}"><th scope="row">${esc(t.name)}</th><td>${t.subjects.map(esc).join(' / ')||'—'}</td><td data-teacher-stat="classCount">${t.classCount}</td><td data-teacher-stat="prepCount">${t.prepCount}</td><td>${t.preps.map(p=>`<span class="teacher-prep-item">${esc(p.grade)} · ${esc(p.subject)} · ${esc(p.track)}级</span>`).join('')||'<span class="empty-teacher-load">当前方案本范围无班级</span>'}</td><td data-teacher-stat="averageClassSize">${average(t.averageClassSize)}</td></tr>`).join('')||'<tr><td colspan="6">暂无教师资料</td></tr>'}</tbody></table></div><p class="teacher-stats-note">同一老师多个同年级、同科目、同层级的平行班算一个课头；兼科在各科分别计入，校区教师总数去重。名册教师在本范围没有班级时保留0班、0课头。</p>`;
}
